test("add は、artboard の並びの末尾に 1 枚足す", () => {
  const { current } = setup();

  act(() => current().hook.add());

  const names = DesignDocument.collectArtboardNames(
    EditorState.document(current().editor.state),
  );
  expect({ length: names.length, leading: names.slice(0, 3) }).toEqual({
    length: 4,
    leading: ["home", "settings", "about"],
  });
});

test("add は、足した artboard を選ぶ", () => {
  const { current } = setup();

  act(() => current().hook.add());

  const { state } = current().editor;
  const added = DesignDocument.collectArtboardNames(
    EditorState.document(state),
  ).slice(3);
  expect(selectedNames(state)).toEqual(added);
});

test("reorder は、並びの中の 1 枚を指した位置へ移す", () => {
  const { current } = setup();

  act(() => current().hook.reorder({ fromIndex: 2, toIndex: 0 }));

  expect(
    DesignDocument.collectArtboardNames(
      EditorState.document(current().editor.state),
    ),
  ).toEqual(["about", "home", "settings"]);
});

test("copy で選んでいるものをコピーすると、別の Box を選んで貼れる", () => {
  const { current } = renderHookOnEditTargets(useEditActions, ["title"]);

  act(() => current().hook.copy());
  act(() => current().editor.dispatch({ type: "select", name: "panel" }));
  act(() => current().editor.dispatch({ type: "paste_copied" }));

  expect(childPositionNamed(current().editor.state, "title-2")).toEqual(
    Option.some({ parentName: "panel", index: 1 }),
  );
});

